function biggestFlippedSum(matrix: number[][]): number {
  const n = matrix.length, cells = n * n;
  const flat = matrix.flat();
  const pairs: number[][] = [];
  for (let i = 0; i < n; i++)
    for (let j = 0; j < n; j++) {
      if (j + 1 < n) pairs.push([i * n + j, i * n + j + 1]);
      if (i + 1 < n) pairs.push([i * n + j, (i + 1) * n + j]);
    }
  const seen = new Set<number>([0]);
  const queue = [0];
  let best = -Infinity;
  for (let q = 0; q < queue.length; q++) {
    const mask = queue[q];
    let sum = 0;
    for (let c = 0; c < cells; c++) sum += mask & (1 << c) ? -flat[c] : flat[c];
    best = Math.max(best, sum);
    for (const [a, b] of pairs) {
      const next = mask ^ (1 << a) ^ (1 << b);
      if (!seen.has(next)) { seen.add(next); queue.push(next); }
    }
  }
  return best;
}

