function biggestFlippedSum(matrix: number[][]): number {
  let total = 0, negatives = 0, minAbs = Infinity;
  for (const row of matrix)
    for (const v of row) {
      total += Math.abs(v);
      if (v < 0) negatives++;
      minAbs = Math.min(minAbs, Math.abs(v));
    }
  return negatives % 2 === 0 ? total : total - 2 * minAbs;
}

